insert into public.blog_posts (id, slug, status, featured, published_at, document)
values
  ('respiracao-quatro-tempos', 'respiracao-quatro-tempos', 'published', false, '2026-09-15', '{"id":"respiracao-quatro-tempos","slug":"respiracao-quatro-tempos","title":"Respirar em quatro tempos quando o dia aperta","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"Inspirar, segurar, soltar, esperar. Um exercício de dois minutos que cabe entre um compromisso e outro — e que funciona melhor quando ninguém percebe.","category":"praticas","author":"Grupo de Práticas","publishedAt":"2026-09-15","readingMinutes":3,"cover":"media/chegada-landscape-mobile.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Respirar em quatro tempos quando o dia aperta","featured":false,"status":"published","content":[{"id":"respiracao-quatro-tempos-1","type":"paragraph","text":"Nem toda pausa precisa de uma sala silenciosa. Algumas cabem na fila, no carro parado, no minuto antes de abrir um e-mail difícil. A respiração em quatro tempos é uma delas: simples o bastante para ser lembrada no meio do aperto."},{"id":"respiracao-quatro-tempos-2","type":"heading","text":"Como fazer"},{"id":"respiracao-quatro-tempos-3","type":"list","items":["Inspire pelo nariz contando até quatro.","Segure o ar contando até quatro, sem forçar.","Solte pela boca contando até quatro.","Fique sem ar por mais quatro tempos e recomece."]},{"id":"respiracao-quatro-tempos-4","type":"paragraph","text":"Três ou quatro voltas bastam. Se contar até quatro parecer longo, comece com três; o ritmo importa mais que o número. Quem tem alguma condição respiratória deve ajustar o exercício com um profissional."},{"id":"respiracao-quatro-tempos-5","type":"quote","text":"A respiração é o único gesto do corpo que acontece sozinho e, ainda assim, aceita ser conduzido."},{"id":"respiracao-quatro-tempos-6","type":"paragraph","text":"Com a prática, o exercício deixa de ser técnica e vira hábito: o corpo passa a lembrar sozinho de desacelerar quando o dia acelera."}],"relatedPostIds":["meditacao-inicio","ritual-da-manha"],"updatedAt":"2026-09-15T12:00:00.000Z"}'::jsonb),
  ('carta-da-semente', 'carta-da-semente', 'published', false, '2026-09-11', '{"id":"carta-da-semente","slug":"carta-da-semente","title":"A carta da Semente e a paciência que não é espera","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"O que foi plantado não pede pressa, pede constância. Uma leitura da carta que aparece quando o resultado ainda não se vê, mas o trabalho já começou.","category":"oraculos","author":"Núcleo de Oráculos","publishedAt":"2026-09-11","readingMinutes":3,"cover":"media/chegada-mobile.webp","coverAlt":"Paisagem contemplativa que acompanha o texto A carta da Semente e a paciência que não é espera","featured":false,"status":"published","content":[{"id":"carta-da-semente-1","type":"paragraph","text":"A Semente costuma sair para quem está no meio de algo que ainda não deu sinal de vida: um projeto recém-começado, uma mudança de hábito, uma conversa que precisa de tempo para amadurecer."},{"id":"carta-da-semente-2","type":"heading","text":"Paciência não é ficar parado"},{"id":"carta-da-semente-3","type":"paragraph","text":"A carta não pede espera passiva. Pede rega: pequenos cuidados diários, feitos mesmo quando nada parece acontecer. É na constância que a semente se decide."},{"id":"carta-da-semente-4","type":"quote","text":"O que foi plantado não pede pressa. Pede constância."},{"id":"carta-da-semente-5","type":"paragraph","text":"Uma pergunta para levar ao dia: o que você plantou recentemente e está tentado a desenterrar só para ver se já brotou?"}],"relatedPostIds":["oraculo-de-hoje","borra-de-cafe"],"updatedAt":"2026-09-11T12:00:00.000Z"}'::jsonb),
  ('primeira-conversa', 'primeira-conversa', 'published', false, '2026-09-09', '{"id":"primeira-conversa","slug":"primeira-conversa","title":"O que acontece na primeira conversa de um atendimento","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"Antes de qualquer técnica, um tempo inteiro para contar a própria história. Como a escuta inicial ajuda a escolher o caminho de cuidado.","category":"terapias","author":"Equipe de Acolhimento","publishedAt":"2026-09-09","readingMinutes":5,"cover":"media/recepcao-acolhimento.webp","coverAlt":"Paisagem contemplativa que acompanha o texto O que acontece na primeira conversa de um atendimento","featured":false,"status":"published","content":[{"id":"primeira-conversa-1","type":"paragraph","text":"Muita gente chega ao Instituto sem saber o nome do que procura. Sabe apenas que algo pesa, cansa ou insiste. A primeira conversa existe justamente para isso: dar tempo ao que ainda não tem nome."},{"id":"primeira-conversa-2","type":"heading","text":"Escutar antes de indicar"},{"id":"primeira-conversa-3","type":"paragraph","text":"Nessa conversa ninguém escolhe técnica. O profissional pergunta sobre o momento de vida, o corpo, o sono, as relações e o que a pessoa espera do cuidado. A indicação vem depois, e pode ser uma só ou uma combinação."},{"id":"primeira-conversa-4","type":"list","items":["Não é preciso trazer diagnóstico.","Tudo o que é dito fica entre a pessoa e a equipe.","Sair sem decisão também é um resultado possível."]},{"id":"primeira-conversa-5","type":"quote","text":"Compreender vem antes de escolher."},{"id":"primeira-conversa-6","type":"paragraph","text":"Para marcar essa conversa, o caminho é a Recepção, pelo WhatsApp ou pessoalmente."}],"relatedPostIds":["ansiedade-corpo","aromaterapia-cotidiano"],"updatedAt":"2026-09-09T12:00:00.000Z"}'::jsonb),
  ('leituras-da-casa', 'leituras-da-casa', 'published', false, '2026-09-07', '{"id":"leituras-da-casa","slug":"leituras-da-casa","title":"Leituras que atravessaram a casa este ano","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"De filosofia oriental a poesia brasileira: os temas que mais circularam entre alunos, terapeutas e visitantes, e por que eles conversam entre si.","category":"cultura","author":"Centro Cultural","publishedAt":"2026-09-07","readingMinutes":6,"cover":"media/palacio-master.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Leituras que atravessaram a casa este ano","featured":false,"status":"published","content":[{"id":"leituras-da-casa-1","type":"paragraph","text":"Uma casa de cuidado também é feita do que se lê nela. Neste ano, algumas estantes se esvaziaram mais rápido que outras, e o movimento diz muito sobre as perguntas de quem passa por aqui."},{"id":"leituras-da-casa-2","type":"heading","text":"O que mais circulou"},{"id":"leituras-da-casa-3","type":"list","items":["Filosofia oriental e textos sobre atenção plena.","Poesia brasileira, lida em voz alta nas rodas de sábado.","Relatos de viagem e de peregrinação.","Livros sobre sono, alimentação e ritmo do corpo."]},{"id":"leituras-da-casa-4","type":"paragraph","text":"Os temas parecem distantes, mas voltam ao mesmo lugar: como viver com mais presença no tempo que se tem."},{"id":"leituras-da-casa-5","type":"quote","text":"Todo livro emprestado volta um pouco diferente, e quem o leu também."}],"relatedPostIds":["cinema-quinta","perguntar-em-grupo"],"updatedAt":"2026-09-07T12:00:00.000Z"}'::jsonb),
  ('voltar-a-estudar', 'voltar-a-estudar', 'published', false, '2026-09-01', '{"id":"voltar-a-estudar","slug":"voltar-a-estudar","title":"Voltar a estudar depois dos quarenta","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"A pergunta não é se ainda dá tempo, e sim o que se quer aprender agora. Conversas de sala de aula sobre recomeçar com calma.","category":"cursos","author":"Coordenação de Cursos","publishedAt":"2026-09-01","readingMinutes":5,"cover":"media/profissionais-encontro.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Voltar a estudar depois dos quarenta","featured":false,"status":"published","content":[{"id":"voltar-a-estudar-1","type":"paragraph","text":"Em quase toda turma nova há alguém que pede desculpas por estar ali. Diz que faz tempo que não estuda, que talvez não acompanhe. Quase sempre é quem mais pergunta, e quem mais aproveita."},{"id":"voltar-a-estudar-2","type":"heading","text":"Aprender com a vida já vivida"},{"id":"voltar-a-estudar-3","type":"paragraph","text":"Quem volta a estudar mais tarde traz uma vantagem que não aparece no currículo: sabe por que está ali. O conteúdo encontra experiências reais onde se apoiar, e a teoria ganha corpo."},{"id":"voltar-a-estudar-4","type":"quote","text":"Conhecimento ganha sentido quando encontra a experiência."},{"id":"voltar-a-estudar-5","type":"paragraph","text":"Se há um tema que você adia há anos, o formulário “Monte seu curso”, na página de Cursos, é um bom lugar para começar a conversa."}],"relatedPostIds":["curso-desenho","caligrafia-como-pausa"],"updatedAt":"2026-09-01T12:00:00.000Z"}'::jsonb),
  ('ritual-da-manha', 'ritual-da-manha', 'published', false, '2026-08-30', '{"id":"ritual-da-manha","slug":"ritual-da-manha","title":"Um ritual de manhã que não pede acordar mais cedo","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"Cinco minutos entre abrir os olhos e pegar o celular. Três gestos simples para começar o dia pelo corpo, e não pela lista de tarefas.","category":"praticas","author":"Grupo de Práticas","publishedAt":"2026-08-30","readingMinutes":4,"cover":"media/atendimentos-vidraca-1.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Um ritual de manhã que não pede acordar mais cedo","featured":false,"status":"published","content":[{"id":"ritual-da-manha-1","type":"paragraph","text":"Rituais de manhã costumam vir com promessas grandes e despertadores mais cedo. Este não. Ele cabe no tempo que você já tem, antes da primeira notificação."},{"id":"ritual-da-manha-2","type":"heading","text":"Três gestos"},{"id":"ritual-da-manha-3","type":"list","items":["Sente-se na cama e sinta os pés no chão por algumas respirações.","Beba um copo de água devagar, prestando atenção na temperatura.","Escolha uma única intenção para o dia, em uma frase curta."]},{"id":"ritual-da-manha-4","type":"paragraph","text":"O celular pode esperar esses cinco minutos. O que ele tem a dizer continuará lá, e você chegará a ele de outro jeito."},{"id":"ritual-da-manha-5","type":"quote","text":"O dia começa onde a atenção começa."}],"relatedPostIds":["meditacao-inicio","respiracao-quatro-tempos"],"updatedAt":"2026-08-30T12:00:00.000Z"}'::jsonb),
  ('aromaterapia-cotidiano', 'aromaterapia-cotidiano', 'published', false, '2026-08-27', '{"id":"aromaterapia-cotidiano","slug":"aromaterapia-cotidiano","title":"Aromaterapia no cotidiano, sem exageros","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"Óleos essenciais não são enfeite nem milagre. Cuidados básicos para quem está começando a usá-los em casa.","category":"terapias","author":"Equipe de Medicina Integrativa","publishedAt":"2026-08-27","readingMinutes":6,"cover":"media/marketplace-contexto.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Aromaterapia no cotidiano, sem exageros","featured":false,"status":"published","content":[{"id":"aromaterapia-cotidiano-1","type":"paragraph","text":"A aromaterapia entra na vida de muita gente por um frasco ganhado de presente. É um bom começo, desde que venha acompanhado de alguns cuidados que o rótulo nem sempre explica."},{"id":"aromaterapia-cotidiano-2","type":"heading","text":"Cuidados básicos"},{"id":"aromaterapia-cotidiano-3","type":"list","items":["Óleo essencial não vai puro na pele: dilua em um óleo vegetal.","Crianças, gestantes e animais pedem orientação específica.","Difusor ligado por períodos curtos, com o ambiente ventilado.","Aroma agradável não substitui tratamento médico."]},{"id":"aromaterapia-cotidiano-4","type":"paragraph","text":"Usada com critério, a aromaterapia é um convite à pausa: um cheiro que marca o fim do expediente, o começo da meditação, a hora de dormir."},{"id":"aromaterapia-cotidiano-5","type":"quote","text":"O cheiro chega antes do pensamento, e por isso sabe acalmar."}],"relatedPostIds":["ansiedade-corpo","primeira-conversa"],"updatedAt":"2026-08-27T12:00:00.000Z"}'::jsonb),
  ('tres-cartas', 'tres-cartas', 'published', false, '2026-08-20', '{"id":"tres-cartas","slug":"tres-cartas","title":"Três cartas na mesa: o que foi, o que é, o que se abre","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"A tiragem mais simples do tarô também é a mais honesta. Como ler três cartas sem transformar a leitura em previsão.","category":"oraculos","author":"Núcleo de Oráculos","publishedAt":"2026-08-20","readingMinutes":4,"cover":"media/journey-cuidado.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Três cartas na mesa: o que foi, o que é, o que se abre","featured":false,"status":"published","content":[{"id":"tres-cartas-1","type":"paragraph","text":"Três cartas lado a lado: a primeira fala do que trouxe você até aqui, a segunda do que está em jogo agora, a terceira do que começa a se abrir. Não é destino. É uma forma de organizar a pergunta."},{"id":"tres-cartas-2","type":"heading","text":"Ler sem prever"},{"id":"tres-cartas-3","type":"paragraph","text":"A tentação é tratar a terceira carta como resposta final. Ela funciona melhor como direção: aponta um movimento possível, que depende do que se faz com as outras duas."},{"id":"tres-cartas-4","type":"quote","text":"O oráculo não adivinha o futuro: ele organiza a pergunta."},{"id":"tres-cartas-5","type":"paragraph","text":"Nas rodas do Núcleo, cada leitura termina com uma pergunta, e não com uma sentença. É ela que a pessoa leva para casa."}],"relatedPostIds":["oraculo-de-hoje","borra-de-cafe"],"updatedAt":"2026-08-20T12:00:00.000Z"}'::jsonb),
  ('perguntar-em-grupo', 'perguntar-em-grupo', 'published', false, '2026-08-16', '{"id":"perguntar-em-grupo","slug":"perguntar-em-grupo","title":"Por que perguntar em grupo muda a pergunta","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"Nas rodas de conversa, a mesma questão soa diferente em cada voz. O que se aprende com encontros abertos sobre temas difíceis.","category":"cultura","author":"Centro Cultural","publishedAt":"2026-08-16","readingMinutes":5,"cover":"media/quem-somos-acolhimento.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Por que perguntar em grupo muda a pergunta","featured":false,"status":"published","content":[{"id":"perguntar-em-grupo-1","type":"paragraph","text":"Sozinhos, costumamos fazer as mesmas perguntas do mesmo jeito. Em roda, alguém sempre a formula de outro modo, e é aí que ela se abre."},{"id":"perguntar-em-grupo-2","type":"heading","text":"Como funciona uma roda"},{"id":"perguntar-em-grupo-3","type":"list","items":["Um tema é proposto, sem resposta pronta.","Cada pessoa fala uma vez antes que alguém fale de novo.","Ninguém precisa concordar para a conversa andar."]},{"id":"perguntar-em-grupo-4","type":"paragraph","text":"O resultado raramente é uma conclusão. Mais comum é sair com a pergunta maior, e com a companhia de quem a carrega junto."},{"id":"perguntar-em-grupo-5","type":"quote","text":"Uma boa pergunta dita em voz alta já não pertence só a quem a fez."}],"relatedPostIds":["cinema-quinta","leituras-da-casa"],"updatedAt":"2026-08-16T12:00:00.000Z"}'::jsonb),
  ('caligrafia-como-pausa', 'caligrafia-como-pausa', 'published', false, '2026-08-12', '{"id":"caligrafia-como-pausa","slug":"caligrafia-como-pausa","title":"Caligrafia como pausa: o traço que obriga a ir devagar","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"Pena, tinta e uma folha: a caligrafia pede o que o dia raramente oferece — atenção a um gesto de cada vez.","category":"cursos","author":"Ateliê Potala","publishedAt":"2026-08-12","readingMinutes":4,"cover":"media/blog-caderno-vela.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Caligrafia como pausa: o traço que obriga a ir devagar","featured":false,"status":"published","content":[{"id":"caligrafia-como-pausa-1","type":"paragraph","text":"Não dá para fazer caligrafia com pressa. A tinta escorre, o traço treme, a letra denuncia. Por isso ela ensina, antes de qualquer alfabeto, a respirar junto com a mão."},{"id":"caligrafia-como-pausa-2","type":"heading","text":"O que se aprende além das letras"},{"id":"caligrafia-como-pausa-3","type":"paragraph","text":"Postura, ritmo, repetição sem tédio. Uma linha inteira da mesma letra parece exercício escolar, mas é meditação disfarçada: cada repetição sai um pouco diferente, e é isso que se aprende a ver."},{"id":"caligrafia-como-pausa-4","type":"quote","text":"O traço mostra a pressa antes de quem escreve perceber que estava com ela."},{"id":"caligrafia-como-pausa-5","type":"paragraph","text":"Não é preciso ter letra bonita para começar. É preciso só aceitar ir devagar."}],"relatedPostIds":["curso-desenho","voltar-a-estudar"],"updatedAt":"2026-08-12T12:00:00.000Z"}'::jsonb),
  ('cuidar-de-quem-cuida', 'cuidar-de-quem-cuida', 'published', false, '2026-08-05', '{"id":"cuidar-de-quem-cuida","slug":"cuidar-de-quem-cuida","title":"Quem cuida também precisa de cuidado","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"Mães, filhos que cuidam dos pais, profissionais de saúde: quem sustenta os outros costuma ser o último a pedir ajuda. Um convite a inverter a ordem.","category":"artigos","author":"Redação Potala","publishedAt":"2026-08-05","readingMinutes":6,"cover":"media/atendimentos-vidraca-4.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Quem cuida também precisa de cuidado","featured":false,"status":"published","content":[{"id":"cuidar-de-quem-cuida-1","type":"paragraph","text":"Existe um cansaço que não passa com uma noite de sono: o de quem passa os dias cuidando de alguém. Ele se acumula em silêncio, porque parece egoísmo reclamar dele."},{"id":"cuidar-de-quem-cuida-2","type":"heading","text":"Sinais de alerta"},{"id":"cuidar-de-quem-cuida-3","type":"list","items":["Irritação constante com pequenas coisas.","Sensação de que o próprio tempo desapareceu.","Culpa ao descansar.","Adiar a própria saúde indefinidamente."]},{"id":"cuidar-de-quem-cuida-4","type":"paragraph","text":"Reconhecer esses sinais não é fraqueza: é o primeiro cuidado. Quem cuida precisa de lugar para ser cuidado também, seja numa terapia, num grupo ou numa conversa franca com a família."},{"id":"cuidar-de-quem-cuida-5","type":"quote","text":"Ninguém sustenta os outros por muito tempo sem ser sustentado."}],"relatedPostIds":["novos-profissionais","sono-estacoes"],"updatedAt":"2026-08-05T12:00:00.000Z"}'::jsonb),
  ('caminhar-em-silencio', 'caminhar-em-silencio', 'published', false, '2026-07-29', '{"id":"caminhar-em-silencio","slug":"caminhar-em-silencio","title":"Caminhar em silêncio: notas sobre andar sem destino","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"Sem fone, sem meta de passos, sem pressa de chegar. O que muda quando a caminhada deixa de ser exercício e vira travessia.","category":"artigos","author":"Redação Potala","publishedAt":"2026-07-29","readingMinutes":7,"cover":"media/home-travessia-mobile.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Caminhar em silêncio: notas sobre andar sem destino","featured":false,"status":"published","content":[{"id":"caminhar-em-silencio-1","type":"paragraph","text":"Caminhar virou tarefa: contamos passos, medimos ritmo, ouvimos alguma coisa para o tempo passar. Caminhar em silêncio devolve à caminhada o que ela tinha de mais antigo, que é pensar com os pés."},{"id":"caminhar-em-silencio-2","type":"heading","text":"Uma proposta simples"},{"id":"caminhar-em-silencio-3","type":"list","items":["Escolha um trajeto conhecido e sem trânsito pesado.","Deixe o celular no bolso, no silencioso.","Caminhe um pouco mais devagar do que o costume.","Repare em três coisas que nunca tinha notado no caminho."]},{"id":"caminhar-em-silencio-4","type":"paragraph","text":"Nos primeiros minutos a cabeça fala sem parar. Depois ela cansa de falar sozinha, e o caminho começa a aparecer."},{"id":"caminhar-em-silencio-5","type":"quote","text":"Todo caminho verdadeiro começa no mundo interno."}],"relatedPostIds":["novos-profissionais","sono-estacoes"],"updatedAt":"2026-07-29T12:00:00.000Z"}'::jsonb)
